import sys

def analyze_binary(data):
    # First, look for strings or patterns
    printable = []
    sequence = []
    for i, b in enumerate(data):
        if 32 <= b <= 126:  # printable ASCII
            sequence.append((i, bytes([b]).decode()))
        else:
            if sequence:
                printable.append(sequence)
            sequence = []

    # Print found strings
    for seq in printable:
        if len(seq) > 3:  # Only show sequences longer than 3 chars
            offset = seq[0][0]
            string = ''.join(c for _, c in seq)
            print(f"[+] Found at offset {hex(offset)}: {string}")

    # Look for potential flag fragments
    for seq in printable:
        string = ''.join(c for _, c in seq)
        if 'flag' in string.lower() or '{' in string or '}' in string:
            offset = seq[0][0]
            print(f"[!] Potential flag fragment at {hex(offset)}: {string}")

def main():
    # Read the original binary
    with open('thoroughlyStripped', 'rb') as f:
        data = f.read()

    print("[*] Analyzing binary content...")
    analyze_binary(data)

if __name__ == "__main__":
    main()

