from pwn import *
import string

def analyze_binary():
    # Read the binary
    with open('/home/ctfplayer/ctf_files/thoroughlyStripped', 'rb') as f:
        data = f.read()

    # Given characters
    chars = "feoytc{nk_}disgla"

    # Look for these characters in the binary
    char_positions = {}
    for i, c in enumerate(data):
        if chr(c) in chars:
            if chr(c) not in char_positions:
                char_positions[chr(c)] = []
            char_positions[chr(c)].append(i)

    # Print character positions and their relative distances
    print("Character positions:")
    for c in chars:
        if c in char_positions:
            print(f"{c}: {char_positions[c]}")
            if len(char_positions[c]) > 1:
                print(f"Distances between occurrences of {c}:")
                distances = [char_positions[c][i+1] - char_positions[c][i] for i in range(len(char_positions[c])-1)]
                print(distances)

    # Look for patterns in sequential bytes
    sequences = []
    for i in range(len(data)-len(chars)):
        seq = data[i:i+len(chars)]
        ascii_chars = [chr(b) for b in seq if chr(b) in string.printable]
        if len(ascii_chars) > 3:  # Look for sequences with multiple printable chars
            sequences.append((i, ''.join(ascii_chars)))

    print("\nPotential sequences:")
    for pos, seq in sequences:
        if any(c in chars for c in seq):
            print(f"Offset {pos}: {seq}")

analyze_binary()
